import java.util.Scanner;

public class VulnerableExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a command: ");
        String command = scanner.nextLine();

        // Vulnerable: Directly executing user input without sanitization
        // This can lead to command injection vulnerabilities
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
***
// Fixed: Using java.util.Scanner with input validation and avoiding direct command execution
import java.util.Scanner;

public class FixedExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a command: ");
        String command = scanner.nextLine();

        // Validate input to prevent command injection
        if (command.matches("^\\w+$")) { // Only allow alphanumeric commands
            try {
                Process process = Runtime.getRuntime().exec(command);
                process.waitFor();
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid command. Only alphanumeric commands are allowed.");
        }
    }
}
